package com.example.busbooking.catalog;

import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;

/**
 * The pairs of cities that have FICTIONAL demo bus services (src/main/resources/data/demo-routes.csv).
 * Each row runs in both directions. "CURATED" rows are the hand-picked ones; the rest are generated by
 * tools/build_demo_data.py so that every state and union territory (except the island territories, which
 * have no road links) has some demo service.
 */
@Component
public class DemoRouteCatalog {

    public record Route(String a, String b, int minutes, int baseFare, String kind) {
        public boolean curated() {
            return "CURATED".equals(kind);
        }
    }

    private final List<Route> routes = new ArrayList<>();

    public DemoRouteCatalog() {
        for (String[] r : CsvReader.read("data/demo-routes.csv")) {
            routes.add(new Route(r[0], r[1], Integer.parseInt(r[2]), Integer.parseInt(r[3]), r[4]));
        }
    }

    /** Curated routes first (this order fixes bus numbers), then the generated ones. */
    public List<Route> routes(boolean includeGenerated) {
        return routes.stream().filter(r -> includeGenerated || r.curated()).toList();
    }
}
